import json


def main():
    base = 1978
    modulus = 1000
    n_max = 400

    # Exhaustive search: for each candidate sum s (ascending), test every
    # pair m < n with m + n = s, m >= 1, n <= n_max, and check whether the
    # last three digits (base^k mod 1000) agree.
    valid_pairs = []
    best = None
    for s in range(3, 2 * n_max):
        for m in range(1, s):
            n = s - m
            if not (1 <= m < n <= n_max):
                continue
            if pow(base, n, modulus) == pow(base, m, modulus):
                valid_pairs.append((m, n))
                if best is None:
                    best = (m, n)
        if best is not None:
            break

    # Independent check: multiplicative order of 978 mod 125 (the odd-prime-power
    # part of the condition), found by direct enumeration.
    order_125 = None
    for k in range(1, 201):
        if pow(base % 1000, k, 125) == 1:
            order_125 = k
            break

    if best is None:
        result = {
            "final_answer": "UNSUPPORTED",
            "evidence": {
                "search_bound_n": n_max,
                "pairs_found": 0,
            },
        }
    else:
        m, n = best
        result = {
            "final_answer": f"m={m}, n={n} (m+n={m + n})",
            "evidence": {
                "m": m,
                "n": n,
                "sum": m + n,
                "last_three_digits_m": pow(base, m, modulus),
                "last_three_digits_n": pow(base, n, modulus),
                "order_of_978_mod_125": order_125,
                "first_valid_pairs_found": valid_pairs[:5],
                "search_bound_n": n_max,
            },
        }

    print(json.dumps(result))


if __name__ == "__main__":
    main()
